import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"AI App Routing & Pages","description":"","frontmatter":{"title":"AI App Routing & Pages"},"headers":[],"relativePath":"en/ai/app/routing.md","filePath":"en/ai/app/routing.md","lastUpdated":1786936077000}'),a={name:"en/ai/app/routing.md"};function r(i,e,n,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="ai-app-routing-pages" tabindex="-1">AI App Routing &amp; Pages <a class="header-anchor" href="#ai-app-routing-pages" aria-label="Permalink to &quot;AI App Routing &amp; Pages&quot;">​</a></h1><blockquote><p>Full route table and guard logic of <code>ai/app/src/router.ts</code> (<code>createAiRouter</code>).</p></blockquote><h2 id="_1-route-overview" tabindex="-1">1. Route Overview <a class="header-anchor" href="#_1-route-overview" aria-label="Permalink to &quot;1. Route Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Name</th><th>View</th><th>Description</th></tr></thead><tbody><tr><td><code>/login</code></td><td><code>login</code></td><td>platform-shared <code>LoginView</code></td><td>Login page (<code>meta.public</code>); standalone mode auto-redirects logged-in users</td></tr><tr><td><code>/auth/callback</code></td><td><code>auth-callback</code></td><td><code>AuthCallbackView</code></td><td>SSO/OAuth callback (<code>meta.public</code>)</td></tr><tr><td><code>/shared/:shareId</code></td><td><code>shared-conversation</code></td><td><code>SharedConversationView</code></td><td>Read-only shared conversation (<code>meta.public</code>)</td></tr></tbody></table><p>Children of <code>AiLayout</code> (sidebar + main content):</p><table tabindex="0"><thead><tr><th>Path</th><th>Name</th><th>View</th></tr></thead><tbody><tr><td><code>/</code></td><td><code>chat</code></td><td><code>AiChatView</code></td></tr><tr><td><code>/rag</code></td><td><code>rag</code></td><td><code>RagKnowledgeBase</code></td></tr><tr><td><code>/memory</code></td><td><code>memory</code></td><td><code>MemoryManagementView</code></td></tr><tr><td><code>/integration</code></td><td><code>integration</code></td><td><code>WorkflowIntegrationView</code></td></tr><tr><td><code>/monitor</code></td><td><code>monitor</code></td><td><code>AiMonitorView</code></td></tr><tr><td><code>/plugins</code></td><td><code>plugin-center</code></td><td><code>PluginCenterView</code></td></tr><tr><td><code>/mcp</code></td><td><code>mcp-manager</code></td><td><code>McpManagerView</code></td></tr><tr><td><code>/workflows</code></td><td><code>agent-workflows</code></td><td><code>AgentWorkflowListView</code></td></tr><tr><td><code>/executions</code></td><td><code>agent-executions</code></td><td><code>AgentExecutionListView</code></td></tr><tr><td><code>/workflows/:id/executions</code></td><td><code>agent-workflow-executions</code></td><td><code>AgentExecutionListView</code></td></tr><tr><td><code>/settings/keys</code></td><td><code>api-keys</code></td><td><code>ApiKeyManagerView</code></td></tr><tr><td><code>/settings/models</code></td><td><code>model-settings</code></td><td><code>ModelSettingsView</code></td></tr><tr><td><code>/settings/embedding</code></td><td><code>embedding-settings</code></td><td><code>EmbeddingSettingsView</code></td></tr><tr><td><code>/settings/templates</code></td><td><code>workflow-templates</code></td><td><code>WorkflowTemplateManagerView</code></td></tr><tr><td><code>/debug/routing</code></td><td><code>routing-debug</code></td><td><code>RoutingDebugView</code></td></tr><tr><td><code>/debug/workflow/:id</code></td><td><code>workflow-debug</code></td><td><code>WorkflowDebugView</code></td></tr><tr><td><code>/debug/harness</code></td><td><code>harness-debug</code></td><td><code>HarnessTraceView</code></td></tr><tr><td><code>/debug/rag</code></td><td><code>rag-debug</code></td><td><code>RagDebugView</code></td></tr><tr><td><code>/evaluation</code></td><td><code>evaluation</code></td><td><code>EvaluationView</code></td></tr><tr><td><code>/schedules</code></td><td><code>schedules</code></td><td><code>ScheduleView</code></td></tr></tbody></table><p>Fullscreen pages (outside <code>AiLayout</code>, with their own top toolbar):</p><table tabindex="0"><thead><tr><th>Path</th><th>Name</th><th>View</th></tr></thead><tbody><tr><td><code>/workflows/:id</code></td><td><code>agent-workflow-designer</code></td><td><code>AgentWorkflowDesignerView</code></td></tr><tr><td><code>/executions/:id</code></td><td><code>agent-execution-detail</code></td><td><code>AgentExecutionDetailView</code></td></tr><tr><td><code>/sidebar</code></td><td><code>sidebar</code></td><td><code>AiSidebarView</code></td></tr></tbody></table><h2 id="_2-guards-public-routes" tabindex="-1">2. Guards &amp; Public Routes <a class="header-anchor" href="#_2-guards-public-routes" aria-label="Permalink to &quot;2. Guards &amp; Public Routes&quot;">​</a></h2><p><code>router.beforeEach</code>:</p><ul><li><code>meta.public</code> routes (<code>login</code> / <code>auth-callback</code> / <code>shared/:shareId</code>) skip auth; in standalone (non-qiankun) mode a logged-in user on <code>login</code> is redirected via <code>resolvePostLoginNavigation</code> to the <code>redirect</code> target</li><li>All other routes go through <code>guardAuthenticatedRoute</code> (platform-shared <code>authSession</code>); unauthenticated users are sent to the login page</li></ul><h2 id="_3-route-base-inference-resolveroutebase" tabindex="-1">3. Route Base Inference (<code>resolveRouteBase</code>) <a class="header-anchor" href="#_3-route-base-inference-resolveroutebase" aria-label="Permalink to &quot;3. Route Base Inference (`resolveRouteBase`)&quot;">​</a></h2><p>Priority (high to low):</p><ol><li>Externally passed <code>routeBase</code> (<code>props.getRouteBase()</code> on qiankun mount; <code>/sidebar</code> when <code>mode === &#39;sidebar&#39;</code>)</li><li>Inferred from <code>window.location.pathname</code> for qiankun container prefixes (matching <code>/schema-platform/app/ai/...</code> or <code>/schema-platform/standalone/ai/...</code>)</li><li><code>VITE_ROUTE_BASE</code> (matches the nginx path in standalone deploys, avoiding double base with BASE_URL)</li><li><code>import.meta.env.BASE_URL</code></li><li>Default <code>/</code></li></ol><h2 id="_4-nav-highlight-rules" tabindex="-1">4. Nav Highlight Rules <a class="header-anchor" href="#_4-nav-highlight-rules" aria-label="Permalink to &quot;4. Nav Highlight Rules&quot;">​</a></h2><p><code>/workflows*</code> and <code>/executions*</code> both activate the &quot;Agent Workflows&quot; sidebar item (see the <code>activeNav</code> rule in <a href="./../design/overview.html">Design Overview</a>).</p><h2 id="_5-related-docs" tabindex="-1">5. Related Docs <a class="header-anchor" href="#_5-related-docs" aria-label="Permalink to &quot;5. Related Docs&quot;">​</a></h2><ul><li><a href="./index.html">App Overview</a> — features and embed modes</li><li><a href="./architecture.html">Architecture &amp; Layers</a> — directory structure and layer inventory</li><li><a href="./../design/overview.html">Design Overview</a> — information architecture and nav wireframes</li></ul>',18)])])}const p=t(a,[["render",r]]);export{g as __pageData,p as default};
